from itertools import permutations, combinations
def sign(p):
    s=1
    for i in range(4):
        for j in range(i+1,4):
            if p[i]>p[j]: s=-s
    return s
A4=[p for p in permutations(range(4)) if sign(p)==1]
assert len(A4)==12
comp=lambda p,q: tuple(p[q[i]] for i in range(4))
found=False
for S in combinations(A4,6):
    Sset=set(S)
    if all(comp(a,b) in Sset for a in S for b in S):
        found=True; break
assert not found

assert 2*3%6==0
for p in [3,5,7,11,13,101]:
    assert all(pow(a,p-1,p)==1 for a in range(1,p))

import random, math
def M(x,p):
    n=len(x)
    if p==0: return math.exp(sum(map(math.log,x))/n)
    return (sum(t**p for t in x)/n)**(1/p)
ps=[-5,-2,-1,-0.5,0,0.5,1,2,3,7]
for _ in range(3000):
    x=[random.uniform(0.1,10) for _ in range(random.randint(2,6))]
    v=[M(x,p) for p in ps]
    assert all(v[i]<=v[i+1]+1e-9 for i in range(len(v)-1))
    assert min(x)-1e-9<=v[2] and v[-3]<=math.sqrt(sum(t*t for t in x)/len(x))+1e-9<=max(x)+1e-8
x=[1,2,7,9]
assert abs(M(x,1e-7)-M(x,0))<1e-5

best=-1; worst=10**9; N=600
for i in range(N+1):
    a=2*i/N
    for j in range(N+1):
        b=2*j/N; c=3-a-b
        if 0<=c<=2:
            v=a**3+b**3+c**3; best=max(best,v); worst=min(worst,v)
assert abs(best-9)<1e-9 and abs(worst-3)<1e-9 and 8+1+0==9

import sympy as sp
x,y,c=sp.symbols('x y c')
assert set(sp.solve(sp.Eq(c*x*y,(c*x)*(c*y)).subs({x:1,y:1}),c))=={0,1}
for f in (lambda t:0*t, lambda t:t):
    assert sp.expand(f(x+y)-f(x)-f(y))==0 and sp.expand(f(x*y)-f(x)*f(y))==0
